from __future__ import annotations

from dataclasses import dataclass, replace
import math

from virvision.scene import BBox, Relation, VisualScene
from virvision.vir.query_filter import ConfidenceThresholds

from .model import Edge, Field, Region, RegionMark


RELATION_TYPES = (
    "left_of",
    "right_of",
    "above",
    "below",
    "near",
    "far",
    "overlapping",
    "inside",
    "contains",
)

_PRIORITY = {
    "inside": 0,
    "contains": 0,
    "overlapping": 1,
    "near": 2,
    "left_of": 3,
    "right_of": 3,
    "above": 3,
    "below": 3,
    "far": 4,
}


def _finite_unit(value, name: str) -> float:
    if (
        isinstance(value, bool)
        or not isinstance(value, (int, float))
        or not math.isfinite(value)
        or not 0 <= value <= 1
    ):
        raise ValueError(f"{name} must be finite and within [0,1]")
    return float(value)


@dataclass(frozen=True)
class SpatialProfile:
    axis_margin: float = 0.02
    near_distance: float = 0.25
    far_distance: float = 0.65
    overlap_iou: float = 0.15
    containment_ratio: float = 0.90
    max_relations_per_unit: int = 4
    max_relations: int = 24

    def __post_init__(self) -> None:
        for name in (
            "axis_margin",
            "near_distance",
            "far_distance",
            "overlap_iou",
            "containment_ratio",
        ):
            object.__setattr__(self, name, _finite_unit(getattr(self, name), f"spatial.{name}"))
        if self.near_distance >= self.far_distance:
            raise ValueError("spatial.near_distance must be smaller than far_distance")
        for name in ("max_relations_per_unit", "max_relations"):
            value = getattr(self, name)
            if isinstance(value, bool) or not isinstance(value, int) or value < 1:
                raise ValueError(f"spatial.{name} must be a positive integer")


@dataclass(frozen=True)
class Anchor:
    id: str
    kind: str
    bbox: BBox
    confidence: float


def region_for_bbox(box: BBox) -> Region:
    center_x = (box.x1 + box.x2) / 2
    center_y = (box.y1 + box.y2) / 2
    column = 0 if center_x < 1 / 3 else 1 if center_x < 2 / 3 else 2
    row = 0 if center_y < 1 / 3 else 1 if center_y < 2 / 3 else 2
    return (
        (Region.UPPER_LEFT, Region.UPPER_CENTER, Region.UPPER_RIGHT),
        (Region.CENTER_LEFT, Region.CENTER, Region.CENTER_RIGHT),
        (Region.LOWER_LEFT, Region.LOWER_CENTER, Region.LOWER_RIGHT),
    )[row][column]


def _area(box: BBox) -> float:
    return (box.x2 - box.x1) * (box.y2 - box.y1)


def _intersection(a: BBox, b: BBox) -> float:
    width = max(0.0, min(a.x2, b.x2) - max(a.x1, b.x1))
    height = max(0.0, min(a.y2, b.y2) - max(a.y1, b.y1))
    return width * height


def _iou(a: BBox, b: BBox) -> float:
    intersection = _intersection(a, b)
    union = _area(a) + _area(b) - intersection
    return intersection / union if union > 0 else 0.0


def _center_distance(a: BBox, b: BBox) -> float:
    ax, ay = (a.x1 + a.x2) / 2, (a.y1 + a.y2) / 2
    bx, by = (b.x1 + b.x2) / 2, (b.y1 + b.y2) / 2
    return math.hypot(ax - bx, ay - by)


def _certainty(observation: float, clarity: float) -> float:
    return min(1.0, observation * (0.60 + 0.40 * min(1.0, max(0.0, clarity))))


def _edge(source: Anchor, predicate: str, target: Anchor, certainty: float) -> Edge:
    return Edge(
        source.id,
        predicate,
        target.id,
        certainty,
        source.kind,
        target.kind,
    )


def edges_for_pair(a: Anchor, b: Anchor, profile: SpatialProfile) -> tuple[Edge, ...]:
    observation = min(a.confidence, b.confidence)
    rows = []
    intersection = _intersection(a.bbox, b.bbox)
    area_a, area_b = _area(a.bbox), _area(b.bbox)
    ratio_a = intersection / area_a if area_a > 0 else 0.0
    ratio_b = intersection / area_b if area_b > 0 else 0.0
    if ratio_a >= profile.containment_ratio:
        score = _certainty(observation, ratio_a)
        rows.extend((_edge(a, "inside", b, score), _edge(b, "contains", a, score)))
    if ratio_b >= profile.containment_ratio:
        score = _certainty(observation, ratio_b)
        rows.extend((_edge(b, "inside", a, score), _edge(a, "contains", b, score)))
    overlap = _iou(a.bbox, b.bbox)
    if overlap >= profile.overlap_iou:
        clarity = (overlap - profile.overlap_iou) / max(1e-12, 1 - profile.overlap_iou)
        first, second = sorted((a, b), key=lambda item: item.id)
        rows.append(_edge(first, "overlapping", second, _certainty(observation, clarity)))
    horizontal_gap = 0.0
    if a.bbox.x2 + profile.axis_margin < b.bbox.x1:
        horizontal_gap = b.bbox.x1 - a.bbox.x2
        clarity = (horizontal_gap - profile.axis_margin) / max(1e-12, 0.25 - profile.axis_margin)
        score = _certainty(observation, clarity)
        rows.extend((_edge(a, "left_of", b, score), _edge(b, "right_of", a, score)))
    elif b.bbox.x2 + profile.axis_margin < a.bbox.x1:
        horizontal_gap = a.bbox.x1 - b.bbox.x2
        clarity = (horizontal_gap - profile.axis_margin) / max(1e-12, 0.25 - profile.axis_margin)
        score = _certainty(observation, clarity)
        rows.extend((_edge(b, "left_of", a, score), _edge(a, "right_of", b, score)))
    vertical_gap = 0.0
    if a.bbox.y2 + profile.axis_margin < b.bbox.y1:
        vertical_gap = b.bbox.y1 - a.bbox.y2
        clarity = (vertical_gap - profile.axis_margin) / max(1e-12, 0.25 - profile.axis_margin)
        score = _certainty(observation, clarity)
        rows.extend((_edge(a, "above", b, score), _edge(b, "below", a, score)))
    elif b.bbox.y2 + profile.axis_margin < a.bbox.y1:
        vertical_gap = a.bbox.y1 - b.bbox.y2
        clarity = (vertical_gap - profile.axis_margin) / max(1e-12, 0.25 - profile.axis_margin)
        score = _certainty(observation, clarity)
        rows.extend((_edge(b, "above", a, score), _edge(a, "below", b, score)))
    distance = _center_distance(a.bbox, b.bbox)
    first, second = sorted((a, b), key=lambda item: item.id)
    if distance <= profile.near_distance:
        clarity = (profile.near_distance - distance) / max(1e-12, profile.near_distance)
        rows.append(_edge(first, "near", second, _certainty(observation, clarity)))
    elif distance >= profile.far_distance:
        clarity = (distance - profile.far_distance) / max(
            1e-12, math.sqrt(2) - profile.far_distance
        )
        rows.append(_edge(first, "far", second, _certainty(observation, clarity)))
    unique = {(item.source, item.predicate, item.target): item for item in rows}
    return tuple(sorted(unique.values(), key=_edge_sort_key))


def _edge_sort_key(item: Edge) -> tuple:
    return (_PRIORITY[item.predicate], -item.certainty, item.source, item.target, item.predicate)


def prune_edges(edges: tuple[Edge, ...], profile: SpatialProfile) -> tuple[Edge, ...]:
    counts: dict[str, int] = {}
    retained = []
    for item in sorted(edges, key=_edge_sort_key):
        if len(retained) >= profile.max_relations:
            break
        if counts.get(item.source, 0) >= profile.max_relations_per_unit:
            continue
        if counts.get(item.target, 0) >= profile.max_relations_per_unit:
            continue
        retained.append(item)
        counts[item.source] = counts.get(item.source, 0) + 1
        counts[item.target] = counts.get(item.target, 0) + 1
    return tuple(retained)


class GeometricEdgeResolver:
    def __init__(
        self,
        profile: SpatialProfile | None = None,
        thresholds: ConfidenceThresholds | None = None,
    ) -> None:
        self.profile = profile or SpatialProfile()
        self.thresholds = thresholds or ConfidenceThresholds()

    def bind(self, scene: VisualScene) -> Field:
        anchors = tuple(
            Anchor(item.id, "unit", item.bbox, item.confidence)
            for item in scene.objects
            if item.confidence >= self.thresholds.object_min
        ) + tuple(
            Anchor(item.id, "trace", item.bbox, item.confidence)
            for item in scene.texts
            if item.confidence >= self.thresholds.ocr_min
        )
        candidates = []
        for left_index, left in enumerate(anchors):
            for right in anchors[left_index + 1 :]:
                candidates.extend(edges_for_pair(left, right, self.profile))
        edges = prune_edges(tuple(candidates), self.profile)
        regions = tuple(
            RegionMark(item.id, item.kind, region_for_bbox(item.bbox)) for item in anchors
        )
        existing = {(item.source, item.predicate, item.target): item for item in scene.relations}
        for item in edges:
            if item.source_kind == "unit" and item.target_kind == "unit":
                existing.setdefault(
                    (item.source, item.predicate, item.target),
                    Relation(item.source, item.predicate, item.target, item.certainty),
                )
        relations = tuple(
            existing[key]
            for key in sorted(existing, key=lambda value: (value[0], value[2], value[1]))
        )
        return Field(replace(scene, relations=relations), regions, edges)
